"""Candidate 2: word-class rule for layer 15's MLP unit 6019 (diffuse; low variance explained).

Fires on words that attach a locating or descriptive phrase to what precedes them:
prepositions (for, in, of, on, to, from, at, with, by, about) and past participles
("-ed" words such as located, based, made). Strongest when the word follows a copula
(is, are, was, were, be, been), as in "X is for Y" or "are made of". Also moderately
positive on demonstratives "those"/"ones" ("such as those"). Near zero elsewhere, and
slightly negative after relative pronouns and conjunctions (that, which, when, and).
Values are the mean activation of each class on training text.
"""
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

PREPOSITIONS = {"for", "in", "of", "on", "to", "from", "at", "with", "by", "about"}
COPULAS = {"is", "are", "was", "were", "be", "been", "being", "am"}
RELATIVES = {"that", "which", "who", "whom", "whose", "when", "where", "while", "and", "but"}
DEMONSTRATIVES = {"those", "ones"}


def step(carry, prefix, upstream: Mapping):
    cur = prefix.token_strings[-1]
    word = cur.strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    after_copula = prev in COPULAS
    if word in PREPOSITIONS:
        value = 1.8 if after_copula else 0.26
    elif cur.startswith(" ") and re.fullmatch(r"[a-z]+ed", word):
        value = 0.54 if after_copula else 0.25
    elif word in DEMONSTRATIVES:
        value = 1.46
    elif word in RELATIVES:
        value = 0.10
    else:
        value = 0.06
    return carry, float(value)

"""Layer 15 MLP down_proj, component 6030: a weak, mostly diffuse readout.

What it is: a rank-one piece of the MLP's down projection. Its activation is the
MLP hidden state read out along one direction (dominated by hidden unit 6030),
scaled by its output norm. The activation is ~0 at the first token of a document,
is near -0.02 on ordinary tokens, and is pulled down by long runs of indentation or
padding spaces, and by the words " of" and " I". It is pulled up by chat and tool
markup tokens such as <|im_start|> and </tool_response>.

What this program captures: those few token-level tendencies. It does not capture
most of the variance, which depends on the whole context and is not readable from the
current token (token identity explains about 3% of it at best, with a full table).
"""

READS = ()

ORDINARY = -0.02  # typical value on ordinary tokens
FIRST_TOKEN = 0.0  # the first token of a document sits at zero


def _is_markup(s):
    return s.startswith("<|") or s.startswith("</") or s == "<think>"


def _value(s):
    if s.strip() == "" and "\n" not in s and len(s) >= 3:
        # indentation or padding: more spaces, more negative (capped)
        return max(-0.6, -0.03 * (len(s) - 2))
    if s == " of":
        return -0.09
    if s == " I":
        return -0.15
    if _is_markup(s):
        return 0.15
    return ORDINARY


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    first_in_doc = prefix.position == 0 or (len(docs) > 1 and docs[-1] != docs[-2])
    if first_in_doc:
        return carry, FIRST_TOKEN
    return carry, _value(prefix.token_strings[-1])

"""Passive and verb-complement feature of layer 15's MLP output, unit 6031.

The component is mostly quiet. It turns on at the words of a passive or modal verb
phrase in running text: the past participle after "be" or a modal ("can be used",
"is analysed", "were converted"), the "be" after a modal ("can be"), and the
preposition or particle that follows a verb ("used as", "converted into",
"subjected to"). It turns slightly negative on a preposition right after "be"
("is in", "was by"). Everything else is zero: the model's own signal here is diffuse,
and surface words explain only a few percent of its variance.
"""

READS = ()

BE = {"be", "is", "are", "was", "were", "been", "being", "am"}
MODALS = {"can", "will", "may", "must", "should", "could", "would", "might", "shall"}
PREPOSITIONS = {"to", "in", "into", "on", "by", "as", "with", "for", "at", "from",
                "through", "using", "over", "up", "out"}
IRREGULAR_PARTICIPLES = {"been", "done", "given", "taken", "made", "known", "shown",
                         "seen", "written", "sold", "put", "set", "led", "read", "built",
                         "held", "found", "kept", "sent", "lost", "brought", "born", "won"}


def is_participle(word):
    """A past participle, by its ending: 'used', 'analysed', 'sent', 'written'."""
    return word.isalpha() and len(word) > 3 and (word.endswith("ed") or word in IRREGULAR_PARTICIPLES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    last = len(doc) - 1
    words = []
    for i in range(last, max(-1, last - 3), -1):
        if doc[i] != doc[last]:
            break
        words.append(prefix.token_strings[i].strip().lower())
    word = words[0]
    prev = words[1] if len(words) > 1 else ""
    if is_participle(word):
        return carry, 1.1 if prev in BE or prev in MODALS else 0.3
    if word == "be" and prev in MODALS:
        return carry, 0.5
    if word in PREPOSITIONS and is_participle(prev):
        return carry, 0.6
    if word in PREPOSITIONS and prev in BE:
        return carry, -0.3
    return carry, 0.0

"""Sentence ends in ordinary prose push this component negative.

The component is near zero on most tokens. It goes strongly negative on the
token that closes a sentence (a full stop, '!' or '?', or one of those with a
line break) when the text around it is ordinary words; a full stop after a
number stays near zero; and line breaks are mildly negative in prose.
"""
import re

READS = ()
WORD = re.compile(r"\s?[A-Za-z]+")
END_NL = {".\n", "。\n", "!\n", "?\n"}
END_PARA = {".\n\n", "?\n\n", "!\n\n"}
END = {".", "。", "!", "?"}
NEWLINE = {"\n", "\n\n", " \n", " \n\n", "\\n", "\r\n"}


def prose(prefix, window=20):
    """Share of the last `window` tokens of this document that are plain words."""
    start = prefix.position
    while start > 0 and prefix.document_ids[start - 1] == prefix.document_ids[-1] and prefix.position - start < window:
        start -= 1
    words = prefix.token_strings[start:-1]
    if not words:
        return 0.0
    return sum(1 for t in words if WORD.fullmatch(t)) / len(words)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if prefix.position > 0 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    p = prose(prefix)
    if tok in END_NL:
        return carry, -8.7 - 2.1 * p
    if tok in END_PARA:
        return carry, 0.8 - 10.5 * p
    if tok in END:
        if re.fullmatch(r"\s*\d+", prev):
            return carry, 0.0
        if WORD.fullmatch(prev) and len(prev.strip()) >= 4:
            return carry, 0.5 - 7.0 * p
        return carry, -2.8 + 1.3 * p
    if tok in NEWLINE:
        return carry, -0.9 - 1.7 * p
    return carry, 0.1

"""Causal connectives: a word that opens a conclusion ("so", "therefore", "thus", "hence",
"因此", ...) drives this component strongly negative; causative "make" words weakly so.
The component is a conclusion-connective detector: it is near 0 on other tokens."""
READS = ()
# conclusion connectives and their typical strength (activation is about -3 on these)
CONCLUDE = {
    "therefore": 3.6, "thus": 3.6, "hence": 3.5, "因此": 3.5, "所以": 3.2, "从而": 1.5,
    "consequently": 2.7, "accordingly": 2.1, "thereby": 1.1, "ので": 2.4, "なので": 2.0, "だから": 1.6,
}
MAKE = {"make": 1.5, "makes": 2.0, "making": 1.5, "made": 1.0}
# words before "so" that make it an intensifier or "do so", not a conclusion
NOT_CONCLUSION = {"do", "did", "does", "is", "was", "are", "were", "be", "been", "am", "not", "doing", "or", "that"}
# punctuation or a clause break before "so" makes it a sentence-level conclusion
BREAK = {",", ".", "!", "?", "and", ";"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in CONCLUDE:
        return carry, -CONCLUDE[word]
    if word == "so":
        if prev in NOT_CONCLUSION:
            return carry, 0.0
        return carry, -(3.0 if prev in BREAK else 2.0)
    if word in MAKE:
        return carry, -MAKE[word]
    return carry, 0.0

"""Layer 15 MLP unit 6052 (through the component p-82af68dd@100000/layers.15.mlp.down_proj:6052).

The component is one rank-one piece of layers.15.mlp.down_proj. Its input vector is about half
MLP hidden unit 6052 of layer 15 (weight 0.70 of a 0.92-norm vector) and the rest spread over
many small units, so its activation is a diffuse readout of layer 15's MLP. Its sign and size
depend on long context that no word list captures. The token-based description we found
explains only about 0.2% of its variance on eval (a per-token lookup table would explain
a few percent), so this program is a coarse summary:

- prepositions (of, in, from, with, through, via, as, like ...) push it negative, the
  strongest and most consistent effect in the data (mean about -0.13);
- determiners (the, a, this ...) are mildly negative (mean about -0.08);
- chat and markup tokens (<|im_start|>, user, assistant, <think>, #include ...) sit near zero;
- "and" / "or" right after a past participle (a passive verb: "are harvested and ...") is
  positive (mean about +0.25), the coordination pattern among its largest positive cases;
- the first token of a document is about zero;
- everything else takes the average value, about -0.05.

Predicted values are in the component's activation units.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

PREPOSITIONS = {
    "of", "in", "on", "at", "from", "with", "through", "via", "over", "for", "as",
    "like", "towards", "toward", "by", "into", "than", "within", "among", "across",
    "about", "against", "between", "under", "without", "during", "after", "before",
}
DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "its", "their"}
MARKUP = {
    "<|im_start|>", "user", "assistant", "<think>", "</think>", "<tool_response>",
    '{"', "#include", "_editor",
}
COORDINATORS = {"and", "or"}
PARTICIPLE_ENDINGS = ("ed", "en")

AVERAGE = -0.05
PREPOSITION_VALUE = -0.13
DETERMINER_VALUE = -0.08
MARKUP_VALUE = 0.0
AFTER_PARTICIPLE_VALUE = 0.25
FIRST_TOKEN_VALUE = 0.0


def step(carry, prefix, upstream: Mapping):
    """The component's activation at the newest token, from the word and the one before it."""
    word = prefix.token_strings[-1].strip().lower()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, FIRST_TOKEN_VALUE
    previous = prefix.token_strings[-2].strip().lower()
    if word in COORDINATORS and previous.endswith(PARTICIPLE_ENDINGS):
        return carry, AFTER_PARTICIPLE_VALUE
    if prefix.token_strings[-1] in MARKUP or word in MARKUP:
        return carry, MARKUP_VALUE
    if word in PREPOSITIONS:
        return carry, PREPOSITION_VALUE
    if word in DETERMINERS:
        return carry, DETERMINER_VALUE
    return carry, AVERAGE

"""Layer 15 MLP down_proj, component 6057, as a word-class rule.

This component writes into the residual stream through one of the MLP's hidden
units (unit 6057 of layer 15). Its activation is largest on the words that carry a
clause's predicate: auxiliaries and modals ("will", "can", "has", "must") and main
verbs, when the clause's subject is a thing rather than a person ("The river
takes", "It uses", "which contains"). After a person subject ("She takes",
"He needs") the verb stays near zero. Copulas ("is", "was", "be") are negative.

The rule reads only the current word and the word before it. A word counts as a
verb when WordNet lists it as one; a subject counts as a thing when the previous
word is it / which / that / this / there, and as a person when it is a personal
pronoun or a human noun. The rule does not parse syntax, so it is a rough summary.
"""

import wordnet

READS = ()

COPULAS = {"be", "been", "being", "is", "are", "was", "were", "am"}
MODALS_AND_AUXILIARIES = {
    "will", "would", "can", "could", "must", "should", "may", "might", "shall",
    "has", "have", "had", "does", "do", "did",
}
PERSON_WORDS = {
    "he", "she", "i", "you", "we", "who", "everyone", "someone", "nobody",
    "everybody", "me", "him", "her", "us", "man", "men", "woman", "women", "boy",
    "girl", "child", "children", "mother", "father", "doctor", "teacher", "student",
    "students", "friend", "friends", "king", "queen", "person", "people", "family",
    "parents", "wife", "husband", "son", "daughter", "brother", "sister", "player",
    "players", "officer", "president", "manager", "adults", "users", "customers",
    "employees", "workers",
}
THING_WORDS = {"it", "which", "that", "this", "there"}
PREDICATE_FOLLOWERS = {"to", "with", "into"}
ADVERBS = {"also", "not", "only", "never", "often", "always", "still", "even", "just"}
DETERMINERS = {
    "the", "a", "an", "of", "these", "those", "their", "his", "her", "its", "my",
    "your", "our", "many", "some", "all", "and", "or", "to", "in", "on", "for",
    "with", "by", "from",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    w = word.strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if not (word.startswith(" ") and w.isalpha() and w.islower()):
        return carry, 0.0
    if w in COPULAS:
        return carry, -0.7
    if w in MODALS_AND_AUXILIARIES:
        return carry, 0.3 if prev in PERSON_WORDS else 1.6
    if w in PREDICATE_FOLLOWERS:
        return carry, 0.35 if prev in THING_WORDS else 0.0
    if w in ADVERBS:
        return carry, 0.3
    pos = wordnet.parts_of_speech(w)
    if "verb" in pos and prev not in DETERMINERS:
        if prev in PERSON_WORDS:
            return carry, 0.0
        verb_only = "noun" not in pos
        if prev in THING_WORDS:
            return carry, 1.4 if verb_only else 0.6
        return carry, 0.5 if verb_only else 0.05
    return carry, 0.0

"""Negation and bare-verb set-up (layer 15 MLP, component 6062).

Reads: a negation word in ordinary prose, and the function word that comes just before a
bare verb in a negated, modal or hypothetical clause. The component fires on:

- the negator itself: "not", "n't", "no", "never", "cannot", "without", "nor", "nothing",
  and their forms in other languages ("не", "不", "没有", "nicht", "pas", "não", "không");
  weaker when the negator is in code, after "if", "=", "(" or "{";
- an auxiliary or infinitive right after a negator within three tokens:
  "did not [go]", "has not [been]", "not [to]", "could [have]";
- "to" after a word of failure or difficulty: "unable to", "failed to", "difficult to";
- other auxiliaries and "to" get a weak value, and the end-of-text token a small negative one.

Only the newest four tokens are read, so the program is stateless.
"""

READS = ()

NEGATORS = {
    "not", "n't", "’t", "'t", "no", "never", "cannot", "without", "nor", "none", "nothing",
    "non", "neither", "nobody", "lack", "unable", "impossible", "refused", "denied",
    "nicht", "pas", "sans", "ohne", "không", "não", "sin", "nie", "не", "без", "无", "没",
    "没有", "不", "不能", "不会", "不是", "無",
}
AUXILIARIES = {
    "to", "have", "has", "had", "be", "been", "being", "were", "was", "is", "are",
    "could", "can", "would", "should", "might", "may", "must", "will", "did", "do", "does",
}
FAILURE_WORDS = {
    "unable", "failed", "failing", "failure", "impossible", "refused", "difficult", "hard",
    "ought", "tried", "tries", "fail",
}
CODE_LEADS = {"if", "=", "(", "{"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    # the up to three tokens before it, in the same document
    near = []
    for k in range(2, 5):
        if len(prefix.token_strings) >= k and prefix.document_ids[-k] == prefix.document_ids[-1]:
            near.append(prefix.token_strings[-k].strip().lower())
    prev = near[0] if near else ""
    if word == "<|endoftext|>":
        return carry, -0.7
    if word in NEGATORS:
        return carry, 0.5 if prev in CODE_LEADS else 1.5
    if word == "to" and prev in FAILURE_WORDS:
        return carry, 2.0
    if word in AUXILIARIES:
        return carry, 1.5 if any(w in NEGATORS for w in near) else 0.3
    return carry, 0.0

"""Concession and appearance-versus-reality contrast, as a negative activation.

Component p-82af68dd@100000/layers.15.mlp.down_proj:6065 (layer 15, MLP down-projection).

What it does: it dips negative when the text opens a concession ("although", "though",
"despite", "even though", "even if", "虽然", "尽管", ...) or talks about how things seem
rather than how they are ("seemingly", "appearance", "looks", "guise", "facade",
"officially", "merely", ...). The deepest dips come on "though" after "even", "despite"
and "seemingly"; the dip fades over the next few words of the concessive clause.
Its output pushes the model toward words like "appearance", "surface", "facade" and
"seeming", so it tracks appearance-versus-reality contrast. Elsewhere it sits near zero.
The one consistent positive value is on the end-of-reasoning marker "</think>".

The program keeps one number, the current level: it jumps to the word's dip, fades by
DECAY per token, and resets at sentence punctuation and at each new document.
"""

READS = ()

# Words that open a concession, with their dip (negative activation) on the word itself.
CONCESSIVE = {
    "although": -5.5, "though": -5.0, "despite": -7.0, "albeit": -5.0, "notwithstanding": -5.0,
    "虽然": -7.0, "尽管": -7.0, "即使": -6.0, "即便": -5.0, "就算": -4.0, "虽": -8.0, "雖然": -6.5,
    "zwar": -5.0, "aunque": -6.0, "хотя": -6.0, "trotz": -5.0, "obwohl": -6.0,
}

# Words about appearance or seeming, with their dip.
APPEARANCE = {
    "seemingly": -8.0, "ostensibly": -8.0, "apparently": -2.5, "seem": -3.0, "seems": -1.5,
    "seemed": -2.0, "looks": -2.0, "look": -1.0, "appear": -2.0, "appears": -1.5,
    "appearance": -1.5, "apparent": -2.0, "outward": -3.0, "outwardly": -3.0, "exterior": -3.0,
    "guise": -6.0, "facade": -4.0, "superficial": -3.5, "pretend": -4.0, "pretending": -6.0,
    "illusion": -2.5, "nominal": -2.0, "officially": -1.6, "formally": -2.0, "technically": -2.5,
    "merely": -2.5, "mere": -1.5, "simply": -1.3, "just": -1.2, "only": -0.6,
    "表面上": -8.0, "表面": -7.0, "外表": -10.0, "外观": -4.0, "看似": -8.0, "看起来": -6.5,
    "看上去": -10.0, "名义上": -7.0, "只是": -3.0, "仅仅是": -11.0,
}

# Other words that often start a concessive clause.
OTHER = {"even": -1.3, "while": -1.1, "regardless": -1.8}

DECAY = 0.6
PUNCTUATION = {".", "!", "?", ";", "\n", "。", "！", "？"}


def dip(word, before):
    """The activation a word itself gets, given the word before it; None if it is no trigger."""
    if word == "</think>":
        return 2.5  # the one consistent positive: the end-of-reasoning marker
    if word == "though":
        if before == "even":
            return -8.3  # "even though"
        if before == "as":
            return 0.0  # "as though" is manner, not concession
        return CONCESSIVE[word]
    if word == "if" and before == "even":
        return -4.6  # "even if"
    if word == "even" and before == ",":
        return -2.8
    if word in CONCESSIVE:
        return CONCESSIVE[word]
    if word in APPEARANCE:
        return APPEARANCE[word]
    return OTHER.get(word)


def step(carry, prefix, upstream):
    """Activation at the newest token: a dip on a concession or appearance word, fading after."""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    level = 0.0 if carry is None else carry
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    value = dip(word, before)
    if value is not None:
        if value == 2.5:
            return 0.0, value  # a point value, no tail
        level = value
    elif word in PUNCTUATION:
        level = 0.0
    else:
        level = level * DECAY
    return level, level

"""Position-in-document version of the component's activation.

The component almost never acts (causal importance above 0.1 at 0 of 10M tokens), and no
token identity or token class predicts its activation. What does show is position: the
first token of a document reads about 0, and the activation drifts down to about -0.1
deeper into a document. This program predicts that drift and nothing else, so it
explains only a little variance (about 0.005 on held-out rows).
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        pos = 0  # first token of a document
    else:
        pos = carry[1] + 1
    if pos == 0:
        value = 0.0
    elif pos <= 10:
        value = -0.02
    elif pos <= 50:
        value = -0.05
    elif pos <= 200:
        value = -0.09
    else:
        value = -0.105
    return (doc, pos), value

"""Second-person address: "you" / "your" as the subject of a question or request.

The component is positive on the words a writer uses to address a reader directly, and
most strongly on "you" right after "can" or "could" ("Can you", "Could you"). It is also
positive on "you" in a chat user turn, after "would / do / are / want / hope / thank",
after "if / when / so", and where the writer talks in the first person ("I", "my") nearby.
It also fires on "please" and on the word right after "Can you" ("Can you help").
It is pushed down when "you" is the object of a marketing-style verb ("help you save",
"keep you", "allow you"). It is about zero in assistant turns and on most other words.
Predictions are scaled by SCALE, since on held-out rows the correlation is lower than in
training data and the best amplitude is smaller. Only these cues are modelled, so the
program explains a small share of the component's variance.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

SCALE = 0.6
SECOND_PERSON = {"you", "your"}
MODALS = {"can", "could"}
OPENERS = {"would", "do", "did", "are", "will", "should", "want", "hope", "maybe", "perhaps",
           "appreciate", "thank", "!", '"', "wish", "think", "know", "love", "like"}
CLAUSE_WORDS = {"if", "when", "so", "that", "as", "but", "what", "which", "where", "how",
                "whether", "because", "while", "then", "and", "or"}
OBJECT_VERBS = {"help", "allow", "allows", "keep", "save", "protect", "enjoy", "check",
                "assure", "here", "below", "make", "let", "get", "give"}
SENTENCE_START = {"", ".", "?", ":"}
FIRST_PERSON = {"i", "my", "me", "myself", "mine", "i'm", "i’m", "i've", "i’ve"}
WINDOW = 30


def step(carry, prefix, upstream: Mapping):
    """carry is the chat role of the latest token: "user", "assistant", "text", or "pending"."""
    toks, docs = prefix.token_strings, prefix.document_ids
    new_doc = len(toks) == 1 or docs[-1] != docs[-2]
    role = "text" if new_doc else carry
    tok = toks[-1]
    word = tok.strip().lower()
    if tok == "<|im_start|>":
        return "pending", 0.0
    if role == "pending":
        return word, 0.0
    if tok == "<|im_end|>" or role == "assistant":
        return ("text" if tok == "<|im_end|>" else role), 0.0
    prev = "" if new_doc else toks[-2].strip().lower()
    prev2 = "" if new_doc or len(toks) < 3 or docs[-3] != docs[-1] else toks[-3].strip().lower()
    if word in SECOND_PERSON:
        if role == "user":
            value = 3.1
        elif prev in MODALS:
            value = 7.6
        elif prev in OPENERS:
            value = 2.0
        elif prev in CLAUSE_WORDS:
            value = 0.7
        elif prev in OBJECT_VERBS:
            value = -0.5
        elif prev in SENTENCE_START:
            value = 0.0
        else:
            value = 0.5
        # first-person speech nearby: the writer is talking to "you"
        start = max(0, len(toks) - 1 - WINDOW)
        speech = sum(
            1
            for t, d in zip(toks[start:-1], docs[start:-1])
            if d == docs[-1] and t.strip().lower() in FIRST_PERSON
        )
        value += 0.9 * min(speech, 3)
    elif word == "please":
        value = 1.3
    elif prev in SECOND_PERSON and prev2 in MODALS:
        value = 5.6
    else:
        value = 0.0
    return role, SCALE * value

"""The 'of' neuron of layer 15's MLP output.

The component writes into the residual stream mainly on the word "of" (about half
of its variance). How strongly it fires on "of" depends on the word just before it:

- after a quantity, share or part-of-a-whole word ("some of", "most of", "majority of",
  "percent of", "portion of") it fires strongly;
- after a reduction or loss noun ("reduction of", "decrease of", "loss of", "waiver of")
  it also fires strongly;
- inside fixed idioms ("instance of", "because of", "instead of", "out of", "kind of",
  "way of") it barely fires;
- elsewhere on "of" it fires at a middling level.

The Romance-language equivalents of "of" ("de", "di") fire weakly. Every other token
is 0.
"""

READS = ()

PART_WORDS = {
    "some", "most", "many", "all", "any", "each", "none", "half", "rest", "one",
    "portion", "majority", "fraction", "proportion", "percent", "%", "part", "number",
    "amount", "lot", "pair", "group", "range", "sum", "total", "variety", "value",
    "reduction", "decrease", "loss", "increase", "removal", "waiver", "weakening",
    "inhibition", "piece", "set", "bit",
}
IDIOM_WORDS = {"instance", "because", "instead", "out", "kind", "way", "member", "use"}
FOREIGN_OF = {" de", " di", " del", " della", " dei"}

OF_PART, OF_OTHER, OF_IDIOM, OF_FOREIGN = 8.0, 5.3, 2.0, 2.5


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in FOREIGN_OF:
        return carry, OF_FOREIGN
    if token != " of":
        return carry, 0.0
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if before in PART_WORDS:
        return carry, OF_PART
    if before in IDIOM_WORDS:
        return carry, OF_IDIOM
    return carry, OF_OTHER

"""Loop headers: how a C-style `for (...)` or `while (...)` header's tokens drive this component.

The component is large only inside loop headers, and mostly on the loop's test and counter:
the `while` keyword, the `(` after it, the `;` that ends a for-loop's initializer (the
largest value), and the loop variable, comparison and bound in the test. Outside headers
it predicts 0; its small, diffuse activity elsewhere is not modelled. Each value is the
average the component takes on that token class in its phase of the header, rounded.
"""
import re

READS = ()
COMPARE = {"<", ">", "<=", ">=", "!=", "=="}
ASSIGN = {"=", "++", "--", "+=", "-=", "+", "-", "*", "/", "%", "int", "let", "var"}
# (phase, class) -> value. Phase 0: before the first ';' (for-init); 1: the test; 2: the update.
VALUE = {
    (0, "ident"): 0.3, (0, "num"): 3.0, (0, "cmp"): 3.0, (0, "punct"): 1.0, (0, "assign"): 0.2,
    (1, "ident"): 6.5, (1, "num"): 2.0, (1, "cmp"): 4.0, (1, "punct"): 2.0, (1, "assign"): 1.0,
    (2, "ident"): 1.5, (2, "num"): 0.5, (2, "cmp"): 0.5, (2, "punct"): 0.3, (2, "assign"): 0.3,
}


def token_class(s):
    if s in COMPARE:
        return "cmp"
    if s in ASSIGN:
        return "assign"
    if re.fullmatch(r"\d+", s):
        return "num"
    if re.fullmatch(r"[A-Za-z_]\w*", s):
        return "ident"
    return "punct"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    s = tok.strip()
    doc = prefix.document_ids[-1]
    st = carry if carry is not None and carry["doc"] == doc else {"doc": doc, "depth": 0, "state": 0, "kw": None, "semis": 0}
    v = 0.0
    if st["state"] == 1:  # a loop keyword was just read; '(' next opens its header
        if s.startswith("("):
            st["state"] = 2
            st["depth"] = s.count("(") - s.count(")")
            st["semis"] = 0
            return st, (10.0 if st["kw"] == "while" else 1.0)
        st["state"] = 0
    if st["state"] == 2:  # inside the header's parentheses
        st["depth"] += s.count("(") - s.count(")")
        if st["depth"] <= 0:
            st["state"] = 0
        if s == ";":
            st["semis"] += 1
            return st, (14.7 if st["semis"] == 1 else 3.9)
        phase = 1 if st["kw"] == "while" else min(st["semis"], 2)
        return st, VALUE.get((phase, token_class(s)), 0.0)
    if s in ("while", "for"):  # a loop keyword opens a possible header
        st["state"] = 1
        st["kw"] = s
        if s == "while":
            v = 9.5 if not tok.startswith(" ") else 1.2
        else:
            v = 1.0 if not tok.startswith(" ") else 0.1
    return st, v
